import{_ as o,a}from"./chunks/3dr_ctrl-n1_cb2_longy_pinout.Ca74F9Pl.js";import{_ as i,C as d,o as n,c as l,j as r,a as s,E as c,al as p}from"./chunks/framework.7vp1BMOE.js";const T=JSON.parse('{"title":"3DR Control N1 Flight Controller","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/3dr_ctrl-n1.md","filePath":"en/flight_controller/3dr_ctrl-n1.md"}'),h={name:"en/flight_controller/3dr_ctrl-n1.md"};function u(b,t,g,m,f,C){const e=d("Badge");return n(),l("div",null,[t[0]||(t[0]=r("h1",{id:"_3dr-control-n1-flight-controller",tabindex:"-1"},[s("3DR Control N1 Flight Controller "),r("a",{class:"header-anchor",href:"#_3dr-control-n1-flight-controller","aria-label":'Permalink to "3DR Control N1 Flight Controller"'},"​")],-1)),c(e,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=p('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact <a href="https://www.3dr.com/" target="_blank" rel="noreferrer">3DR</a> for hardware support or compliance issues.</p></div><p>The <em>3DR Control N1</em> is a compact, high-performance, low-profile and lightweight flight controller designed and assembled in USA. It runs PX4 on the <a href="https://nuttx.apache.org/" target="_blank" rel="noreferrer">NuttX</a> OS.</p><p><img src="'+o+'" alt="3DR Control N1"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This flight controller requires a carrier board to work correctly. Visit <a href="https://3dr.wiki/autopilots/control-n1/" target="_blank" rel="noreferrer">3DR</a> for available carrier boards and purchase information.</p></div><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Processor:</strong> STMicro STM32H743 Arm Cortex-M7 up to 480 MHz, 1 MB RAM, 2 MB flash, 8 MB external flash</li><li><strong>Sensors:</strong><ul><li>2x InvenSense IIM-42653 IMU (6-DoF)</li><li>Asahi Kasei AK09940A magnetometer</li><li>Infineon DPS368 barometer</li></ul></li><li><strong>Interfaces:</strong><ul><li>12x PWM motor outputs (DShot, bidirectional DShot, GPIO)</li><li>7x serial ports (3x with hardware flow control)</li><li>2x FD-CAN (up to 8 Mbps)</li><li>2x I2C (up to 400 kHz)</li><li>1x SPI (up to 40 MHz)</li><li>4x GPIO (push-pull, direct from MCU)</li><li>1x USB Full Speed (native STM32H7 port)</li><li>1x SDIO/SDMMC interface</li><li>1x addressable LED output (NeoPixel-compatible)</li><li>Serial Wire Debug (SWD)</li></ul></li><li><strong>Dimensions:</strong> 28 × 17.6 × 3.7 mm</li><li><strong>Weight:</strong> 2.32 g</li><li><strong>Input Voltage:</strong> 4.8 – 6.0 V</li><li><strong>Typical Current draw</strong>: ~230 mA</li><li><strong>Operating Temperature:</strong> -20 to 75 °C</li><li><strong>Storage Temperature:</strong> -40 to 85 °C</li></ul><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected (PX4 v1.18 and later).</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3dr_ctrl-n1_default</span></span></code></pre></div><h2 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h2><p>The Control N1 uses three Hirose DF40-series board-to-board connectors:</p><table tabindex="0"><thead><tr><th>Connector</th><th>Pins</th><th>Part Number</th><th>Signals</th></tr></thead><tbody><tr><td>J100</td><td>30</td><td>DF40HC(3.5)-30DS-0.4V(51)</td><td>USART1, USART2, USART3, UART4, SDMMC, USB, ALARM</td></tr><tr><td>J200</td><td>30</td><td>DF40HC(3.5)-30DS-0.4V(51)</td><td>USART6, FDCAN1, SPI, SWD, LED, BRD_EN</td></tr><tr><td>J300</td><td>80</td><td>DF40HC(3.5)-80DS-0.4V(51)</td><td>UART7, UART8, FDCAN2, I2C, ADC, Motor outputs CH1–CH12</td></tr></tbody></table><h2 id="pinout" tabindex="-1">Pinout <a class="header-anchor" href="#pinout" aria-label="Permalink to &quot;Pinout&quot;">​</a></h2><p>This board is designed to be used with different carrier boards.</p><p>For the full pinout, visit the <a href="https://docs.3dr.com/autopilots/control-n1/#pinout" target="_blank" rel="noreferrer">3DR Control N1 Pinout Tool</a>.</p><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Connector</th><th>Peripheral</th><th>Flow Control</th><th>Default Function</th></tr></thead><tbody><tr><td>SG1</td><td>J100</td><td>USART2</td><td>Yes</td><td>TELEM1</td></tr><tr><td>SG2</td><td>J100</td><td>UART4</td><td>Yes</td><td>TELEM2</td></tr><tr><td>SG3</td><td>J300</td><td>UART7</td><td>Yes</td><td>User</td></tr><tr><td>SG4</td><td>J100</td><td>USART3</td><td>No</td><td>GPS2</td></tr><tr><td>SG5</td><td>J100</td><td>USART1</td><td>No</td><td>User</td></tr><tr><td>SG6</td><td>J200</td><td>USART6</td><td>No</td><td>RC</td></tr><tr><td>SG7</td><td>J300</td><td>UART8</td><td>No</td><td>GPS1</td></tr></tbody></table><h2 id="pwm-outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm-outputs" aria-label="Permalink to &quot;PWM Outputs&quot;">​</a></h2><p>The Control N1 has 12 PWM outputs, all routed through connector J300. All outputs are FMU outputs with no separate IO coprocessor.</p><p>Each output supports PWM, OneShot, DShot, and bidirectional DShot. GPIO mode is also available on all channels.</p><p>Outputs are grouped for DShot timing purposes. All channels within a group must use the same protocol and rate.</p><table tabindex="0"><thead><tr><th>Group</th><th>Channels</th></tr></thead><tbody><tr><td>Group 1</td><td>CH1–CH4</td></tr><tr><td>Group 2</td><td>CH5–CH8</td></tr><tr><td>Group 3</td><td>CH9–CH12</td></tr></tbody></table><h2 id="rc-setup" tabindex="-1">RC Setup <a class="header-anchor" href="#rc-setup" aria-label="Permalink to &quot;RC Setup&quot;">​</a></h2><p>Serial port SG6 (USART6, connector J200) is mapped to <code>RC</code> by default and supports any protocol compatible with PX4&#39;s COMMON_RC driver: ELRS, CRSF, DSM/DSMX, GHST, and SBUS.</p><p>Connect your RC receiver&#39;s serial output to the SG6 RX line on J200. Select and assign your preferred protocol in QGroundControl during initial setup.</p><h2 id="carrier-boards" tabindex="-1">Carrier Boards <a class="header-anchor" href="#carrier-boards" aria-label="Permalink to &quot;Carrier Boards&quot;">​</a></h2><p>The Control N1 is designed to be used with a carrier board. The following carrier boards are available from 3DR:</p><table tabindex="0"><thead><tr><th>Board</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://docs.3dr.com/autopilots/carrier-boards/r0026-cb1-cuby/" target="_blank" rel="noreferrer">CB1 Cuby</a></td><td>Compact square form factor</td></tr><tr><td><a href="https://docs.3dr.com/autopilots/carrier-boards/r0027-cb2-longy/" target="_blank" rel="noreferrer">CB2 Longy</a></td><td>Thin form factor for space-constrained builds</td></tr><tr><td><a href="https://docs.3dr.com/autopilots/carrier-boards/r0033-cb3-fpv/" target="_blank" rel="noreferrer">CB3 FPV</a></td><td>Optimized for FPV platforms</td></tr><tr><td><a href="https://docs.3dr.com/autopilots/carrier-boards/r0036-cb4-wing/" target="_blank" rel="noreferrer">CB4 Wing</a></td><td>Fixed-wing and VTOL applications</td></tr><tr><td><a href="https://docs.3dr.com/autopilots/carrier-boards/r0037-cn1-prototyping-board/" target="_blank" rel="noreferrer">CN1 Prototyping Board</a></td><td>Full signal access for development</td></tr><tr><td><a href="https://docs.3dr.com/autopilots/carrier-boards/r0034-cn1-to-czoem-adapter/" target="_blank" rel="noreferrer">CN1 to CZ OEM Adapter</a></td><td>Adapter for Control Zero OEM carrier boards</td></tr></tbody></table><p>The image below shows the pinout of the CB2 Longy as a reference for connector layout and signal assignment.</p><p><img src="'+a+'" alt="3DR Control N1 CB2 Longy Pinout"></p><h2 id="debug-port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug-port" aria-label="Permalink to &quot;Debug Port&quot;">​</a></h2><p>The <a href="./../debug/swd_debug">SWD debug port</a> signals (SWCLK, SWDIO) and BOOT0 are routed through connector <strong>J200</strong> on the Control N1 module. The physical debug interface (connector type, pinout, and location) depends on the carrier board.</p><p>Depending on the carrier board, the debug connector may be a TC2030-compatible pad-of-nails (requires a <a href="https://www.tag-connect.com/product/tc2030-ctx-nl-6-pin-no-legs-cable-with-10-pin-micro-connector-for-cortex-processors" target="_blank" rel="noreferrer">Tag-Connect TC2030</a> cable) or a 14-pin ARM Cortex JTAG/SWD header (Samtec FTSH-107, 2×7, 1.27 mm pitch). Note that some carrier boards may not expose a debug interface. Refer to your carrier board&#39;s documentation for the exact connector location and pinout.</p><h2 id="further-information" tabindex="-1">Further Information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further Information&quot;">​</a></h2><ul><li><a href="https://docs.3dr.com/autopilots/control-n1/" target="_blank" rel="noreferrer">3DR Control N1 documentation</a></li></ul>',37))])}const P=i(h,[["render",u]]);export{T as __pageData,P as default};
